set title = 'Monsoon Romance, City Edge',
    description = 'Wet pavement, silk, oxidised silver, cotton, denim, and antique gold. The mood is cinematic, intimate, and a little rebellious.',
    colors = array['#111113','#f3eee7','#9d6474','#b39252','#53687c'],
    textures = array['wet pavement','silk','oxidised silver','cotton','denim'],
    keywords = array['cinematic','intimate','soft rebellion','Indian romantic','city muse'],
    image_board_urls = '{}',
    linked_articles = array['22222222-1028-4222-8222-222222222222'::uuid,'22222222-1001-4222-8222-222222222222'::uuid]
where id = '55555555-5555-4555-8555-555555555555';
